import { MeshStandardNodeMaterial, DoubleSide } from 'three/webgpu';
import { color, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight } = ctx.THREE;

  const group = new Group();
  const timelines = [];

  // Colors from specification
  const palette = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. STAGE & BACKDROP: Create a self-contained card container to prevent void
  const cardWidth = 2.4;
  const cardHeight = 1.6;

  // Local card background mesh
  const bgGeom = new PlaneGeometry(cardWidth, cardHeight);
  const bgMat = new MeshStandardNodeMaterial({
    color: palette.surface,
    roughness: 0.2,
    metalness: 0.8,
    clearcoat: 1.0,
    clearcoatRoughness: 0.1,
    side: DoubleSide
  });
  const bgMesh = new Mesh(bgGeom, bgMat);
  group.add(bgMesh);

  // Accent subtle frame/edge (active on highlight/hover)
  const edgeWidth = 0.04;
  const edgeTopGeom = new PlaneGeometry(cardWidth, edgeWidth);
  const edgeTopMat = new MeshStandardNodeMaterial({
    color: palette.ink,
    roughness: 0.5,
    metalness: 0.2
  });
  const edgeTop = new Mesh(edgeTopGeom, edgeTopMat);
  edgeTop.position.set(0, cardHeight / 2 - edgeWidth / 2, 0.01);
  group.add(edgeTop);

  // 2. TEXTURE OVERLAY
  const imgGeom = new PlaneGeometry(cardWidth * 0.9, cardHeight * 0.8);
  const imgMat = new MeshStandardNodeMaterial({
    transparent: true,
    opacity: 0.35,
    roughness: 0.5,
    metalness: 0.1,
    blending: ctx.THREE.AdditiveBlending,
    depthWrite: false
  });
  const imgMesh = new Mesh(imgGeom, imgMat);
  imgMesh.position.set(0, 0, 0.02);
  group.add(imgMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      imgMat.map = texture;
      imgMat.needsUpdate = true;
    }).catch(err => console.warn('Failed to load image texture:', err));
  }

  // 3. TEXT ACCENT
  // Fetch local text contents safely
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textStr = items[0]?.text ?? 'Journal 3';

  // Render text content using ctx.fontAtlas (JetBrains Mono-like display)
  const textObj = ctx.fontAtlas.createText(textStr, {
    fontSize: 34, // mapped to Atlas pixel height approx
    color: palette.paper,
    align: 'center'
  });
  // Position text cleanly onto container plane
  textObj.position.set(0, -0.2, 0.04);
  textObj.scale.setScalar(0.0065); // Scale down font Atlas to fit nicely inside the bounds
  group.add(textObj);

  // 4. ENGINEERED LIGHTING (Local to show off metallic properties of surface)
  const localLight = new DirectionalLight(palette.paper, 1.2);
  localLight.position.set(2, 2, 3);
  group.add(localLight);

  const localAccentLight = new DirectionalLight(palette.accent, 1.5);
  localAccentLight.position.set(-2, -2, 2);
  group.add(localAccentLight);

  // 5. MOTION & INTERACTION
  let isHovered = false;

  const onOver = () => {
    isHovered = true;

    // Smooth lift & accent color highlight
    const tl = gsap.timeline();
    tl.to(group.position, {
      z: 0.15,
      y: '+=0.05',
      duration: 0.4,
      ease: 'power3.out'
    }, 0);

    tl.to(edgeTopMat.color, {
      r: 1.0, // Shift edge towards signal red accent
      g: 0.16,
      b: 0.22,
      duration: 0.3
    }, 0);

    tl.to(imgMesh.position, {
      z: 0.08,
      duration: 0.4,
      ease: 'power3.out'
    }, 0);

    timelines.push(tl);
  };

  const onOut = () => {
    isHovered = false;

    const tl = gsap.timeline();
    tl.to(group.position, {
      z: 0.0,
      y: '-=0.05',
      duration: 0.5,
      ease: 'power2.out'
    }, 0);

    tl.to(edgeTopMat.color, {
      r: 0.086, // back to soft ink dark
      g: 0.086,
      b: 0.113,
      duration: 0.4
    }, 0);

    tl.to(imgMesh.position, {
      z: 0.02,
      duration: 0.5,
      ease: 'power2.out'
    }, 0);

    timelines.push(tl);
  };

  const onClick = () => {
    // Elegant press-down action with settle overshoot
    const tl = gsap.timeline();
    tl.to(group.scale, {
      x: 0.94,
      y: 0.94,
      z: 0.94,
      duration: 0.1,
      ease: 'power4.out'
    });
    tl.to(group.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.7,
      ease: 'elastic.out(1, 0.3)'
    });

    timelines.push(tl);

    // Emit navigate/select event bus signal
    ctx.emit('hub-journal.select', { id: 'journal-3', label: textStr });
  };

  // Wire pointers to returned object's userData
  group.userData.handlers = {
    pointerover: onOver,
    pointerout: onOut,
    click: onClick
  };

  // Clean-up hook
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    bgGeom.dispose();
    bgMat.dispose();
    edgeTopGeom.dispose();
    edgeTopMat.dispose();
    imgGeom.dispose();
    imgMat.dispose();
  };

  return group;
}
